{"cards": [{"node_code": "N_5639abb49814df1f", "definition": "研究水泥混凝土路面在服役期间及设计阶段所表现出的力学、物理及功能特性，包括抗折强度、抗滑性、平整度、接缝性能及材料微观结构特征。", "boundary": "本节点聚焦于混凝土路面结构层本身的“属性”与“状态”。边界在于区分“性能指标”与“外部荷载”：车辆、温度等外部因素归入“作用”节点；本节点关注结构层如何响应这些作用，如应力分布、变形模量、疲劳寿命及表面构造。不包含路基土体性能或沥青混合料性能。", "includes": ["混凝土路面的力学性能（抗折、抗压、弹性模量）及物理性能（抗渗、抗冻）", "路面功能性能（抗滑、平整度、噪声）及接缝处的局部性能表现", "材料微观结构对宏观性能的影响及性能退化机理分析"], "excludes": ["作用于路面的车辆荷载、温度场及环境作用（归入“作用”节点）", "路面结构层的厚度计算、配筋设计及组合优化（归入“结构设计”节点）"], "sibling_distinctions": [{"other_code": "N_b9e90eaa6d19b3c0", "rule": "本节点关注结构层“自身”的特性与响应结果（如强度、变形）；兄弟节点关注施加在结构层上的“外部”因素（如荷载、温度、湿度）。"}, {"other_code": "N_3270a4f1a44499e4", "rule": "本节点关注性能指标的定义、测试与机理；兄弟节点关注基于性能指标进行的设计计算、参数确定与方案优化。"}, {"other_code": "N_73f35a834f3816b4", "rule": "本节点侧重静态或短期/中期的性能表征；兄弟节点侧重长期服役下的性能衰减规律、寿命预测及耐久性评估方法。"}], "cross_boundary_rule": "当研究内容涉及“荷载-响应”关系时，若重点在于荷载模型建立归入“作用”，若重点在于结构层在荷载下的应力/应变/破坏模式归入本节点。"}, {"node_code": "N_b9e90eaa6d19b3c0", "definition": "研究作用于水泥混凝土路面的各类外部因素及其力学效应，包括交通荷载、温度变化、湿度影响、冻融循环及地基反力等。", "boundary": "本节点聚焦于路面结构层所承受的“输入”条件。边界在于区分“外部作用”与“内部响应”：结构层内部的应力、变形及破坏归入“性能”或“结构设计”节点；本节点关注荷载谱分析、温度梯度分布、环境作用模型及地基-路面相互作用中的外部约束条件。不包含路面材料本身的性能测试。", "includes": ["车辆轴载、轮载及其组合的交通荷载模型与统计特征", "温度场分布、温度梯度、湿度变化及冻融等环境作用分析", "地基反力、边界约束条件及荷载-地基相互作用的外部力学模型"], "excludes": ["路面结构层在荷载作用下的内部应力、应变及破坏机理（归入“性能”节点）", "基于荷载作用进行的路面结构厚度与配筋设计计算（归入“结构设计”节点）"], "sibling_distinctions": [{"other_code": "N_5639abb49814df1f", "rule": "本节点关注“因”（外部荷载与环境）；兄弟节点关注“果”（结构层的力学与功能表现）。"}, {"other_code": "N_3270a4f1a44499e4", "rule": "本节点关注作用模型的建立与参数化；兄弟节点关注利用作用模型进行结构安全度与尺寸的设计计算。"}], "cross_boundary_rule": "当研究“荷载-响应”耦合时，若侧重荷载的识别、建模与统计特性归入本节点；若侧重结构层对荷载的力学响应机制归入“性能”节点。"}]}
